const body = $json.body ?? $json;
const name = String(body.name ?? '').trim();
const email = String(body.email ?? '').trim().toLowerCase();
const need = String(body.need ?? '').trim();
if (!name || !email || !need) throw new Error('Required fields: name, email, need');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) throw new Error('Invalid email format');
const budget = Number(body.budget ?? 0);
const timeline = String(body.timeline ?? '').toLowerCase();
const company = String(body.company ?? '').trim();
let score = 0;
if (Number.isFinite(budget) && budget >= 1000) score += 30;
if (/30 days|1 month|asap/.test(timeline)) score += 25;
if (company) score += 20;
if (/api|automation|cloud|development/i.test(need)) score += 25;
const priority = score >= 70 ? 'Hot' : score >= 40 ? 'Warm' : 'Nurture';
return [{ json: { name, email, company, need, budget: Number.isFinite(budget) ? budget : 0, timeline, source: String(body.source ?? 'unknown'), score, priority, receivedAt: new Date().toISOString(), nextAction: priority === 'Hot' ? 'Respond within one business day' : priority === 'Warm' ? 'Schedule a discovery follow-up' : 'Add to nurture sequence' } }];
